,create_address_subdomain_match_force_enable:{en:"Force Enable",zh:"强制开启"},create_address_subdomain_match_note:{en:"RANDOM_SUBDOMAIN_DOMAINS already allows random or manual subdomains for listed base domains. This switch additionally allows API callers to specify subdomains under other allowed base domains.",zh:"RANDOM_SUBDOMAIN_DOMAINS 已允许在所列基础域名下随机生成或手动输入子域名；此开关额外允许 API 在其他已授权基础域名下指定子域名。"},create_address_subdomain_match_tip:{en:"Only affects /api/new_address and /admin/new_address domain validation. Example: when enabled, foo.example.com can match configured base domain example.com.",zh:"仅影响 /api/new_address 和 /admin/new_address 的域名校验。例如开启后，foo.example.com 可以匹配已配置的基础域名 example.com。"},delete_rule:{en:"Delete",zh:"删除"},delete_rule_confirm:{en:"Are you sure you want to delete this rule?",zh:"确定要删除这条规则吗？"},delete_success:{en:"Delete Success",zh:"删除成功"},domain_list:{en:"Domain List (Optional)",zh:"域名列表（可选）"},email_forwarding_config:{en:"Email Forwarding Configuration",zh:"邮件转发配置"},forward_address:{en:"Forward Address",zh:"转发地址"},forward_address_required:{en:"Forward address is required",zh:"转发地址不能为空"},forward_placeholder:{en:"forward@example.com",zh:"forward@example.com"},forwarding_rule_warning:{en:"Each rule will run independently. Forward address needs to be a verified address.",zh:"每条规则独立运行，转发地址需要为已验证的地址。"},fromBlockList:{en:"Block Keywords for receive email",zh:"接收邮件地址屏蔽关键词"},manualInputPrompt:{en:"Type and press Enter to add",zh:"输入后按回车键添加"},match_all:{en:"All",zh:"全部"},match_any:{en:"Any",zh:"任一"},noLimitSendAddressList:{en:"No Balance Limit Send Address List",zh:"无余额限制发送地址列表"},regex_invalid:{en:"Invalid regex pattern",zh:"无效的正则表达式"},regex_too_long:{en:"Regex pattern too long (max 200 characters)",zh:"正则表达式过长（最大200字符）"},rule_index:{en:"Rule",zh:"规则"},save:{en:"Save",zh:"保存"},select_domain:{en:"Select Domain",zh:"选择域名"},send_address_block_list:{en:"Address Block Keywords for send email",zh:"发送邮件地址屏蔽关键词"},send_mail_daily_limit:{en:"Daily Limit",zh:"每日额度"},send_mai